        if ($candidate->getValidFrom() <= $event->getTs()) {
            if ($row === null || $candidate->getValidFrom() > $row->getValidFrom()) {
                $row = $candidate;
            }
        }
    }
    if ($row === null) {
        $unrated[] = $event;
        continue;
